                                    paidCents: number;
                                    /** @description Refunds waiting for approval */
                                    pendingRefundCents: number;
                                    /** @description Refunds done (a failed card refund is not counted) */
                                    refundedCents: number;
                                    /** @description A card refund the processor reported failed: that money was not given back */
                                    refundFailed: boolean;
                                    /** @description A card refund sent to the processor and not confirmed yet (it already counts as refunded) */
                                    refundSending: boolean;
                                    /** @description What the newest deposit link asks for; null without one */
                                    requestedCents: number | null;
