                                needsPriceConfirm: boolean;
                                /** @description No size known: priced at the smallest size (the starting price) until staff confirm the size at the shop ("Confirm size") */
                                needsSizeConfirm: boolean;
                                pickupState: ("pending" | "collected") | null;
