                                needsPriceConfirm: boolean;
                                /** @description No size known: priced at the smallest size (the starting price) until staff confirm the size at the shop ("Confirm size") */
                                needsSizeConfirm: boolean;
                                pickupState: ("pending" | "collected") | null;
                                plannedBay: {
                                    id: string;
                                    number: number;
                                } | null;
                                prepped: boolean;
                                scheduledEnd: string;
                                scheduledStart: string;
                                seq: number;
                                /** @enum {string} */
                                status: "booked" | "confirmed" | "arrived" | "cleaning" | "completed" | "canceled" | "no_show";
                                /** @description The vehicle size the visit is priced at (a size key); null when nobody knew it */
                                vehicleClass: string | null;
                                /** @description "Large SUV" */
                                vehicleClassLabel: string | null;
                                version: number;
