    "/api/v1/appointments/quote": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Price preview for the booking sheet (nothing is written)
         * @description The same rules as the booking (ADR 0170): the size named, else the vehicle’s size on file, else unknown (the smallest size’s price, the "starts at" price); a client who holds or shares an active membership gets the member price, and a line an inclusion covers by itself at completion (`autoApply`, or every inclusion for a member with `autoApply`) shows the regular price with what the membership will cover (up to the price at the plan size) and the size difference due; an inclusion staff apply by hand is not shown as covered. Coverage itself is applied when the visit is completed.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        addonIds?: string[];
                        /** @description The client (their membership prices the visit); absent: a guest */
                        customerId?: string | null;
                        /** Format: uuid */
                        serviceId: string;
                        vehicleClass?: string | null;
                        /** @description One of the client’s vehicles: its size on file prices the visit when no vehicleClass is named */
                        vehicleId?: string | null;
                    };
                };
            };
            responses: {
                /** @description Default Response */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            lines: {
                                /**
                                 * @description How a price was found: class (the size's own price), unknown_class (no size known: the smallest size's), estimated (the size has no price: the starting price), base (the service has no prices by size), legacy (priced before sizes)
                                 * @enum {string}
                                 */
                                basis: "legacy" | "class" | "unknown_class" | "estimated" | "base";
                                /** @description What the line would charge */
                                chargeCents: number;
                                coverage: {
                                    coveredCents: number;
                                    differenceCents: number;
                                    label: string;
                                    planClassLabel: string | null;
                                } | null;
                                discountBp: number;
                                dueCents: number;
                                /** @enum {string} */
                                kind: "package" | "addon";
                                listCents: number;
                                /** @description The top of a range (tint) */
                                listMaxCents: number | null;
                                memberDiscountCents: number;
                                name: string;
                                serviceId: string;
                            }[];
                            member: {
                                discountBp: number;
                                /** @description The client shares the membership as a household member */
                                household: boolean;
                                planClass: string;
                                planClassLabel: string | null;
                                tierName: string;
                            } | null;
                            /** @description What the visit was priced at (ADR 0170) */
                            pricing: {
                                /**
                                 * @description How a price was found: class (the size's own price), unknown_class (no size known: the smallest size's), estimated (the size has no price: the starting price), base (the service has no prices by size), legacy (priced before sizes)
                                 * @enum {string}
                                 */
                                basis: "legacy" | "class" | "unknown_class" | "estimated" | "base";
                                /** @description A price depends on a size not known yet, or the size has no price of its own: the exact price is confirmed at the shop */
                                confirmAtShop: boolean;
                                /** @description Priced as a member (the holder or a household member of an active membership) */
                                member: boolean;
                                needsPriceConfirm: boolean;
                                needsSizeConfirm: boolean;
                                totals: {
                                    /** @description What the membership would cover (applied when the visit is completed) */
                                    coveredCents: number;
                                    /** @description Sum of the member % off */
                                    discountCents: number;
                                    /** @description What the client owes before tax and tip */
                                    dueCents: number;
                                    /** @description Sum of the regular prices at the size */
                                    listCents: number;
                                };
                                vehicleClass: string | null;
                                vehicleClassLabel: string | null;
                            };
                        };
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
