                                    receiptNumber: string | null;
                                    /** @description Square’s receipt page of a Square payment, only an https page on squareup.com or squareupsandbox.com; null otherwise */
                                    receiptUrl: string | null;
                                    resolvedAt: string | null;
                                    seq: number;
                                    /** @enum {string} */
                                    source: "oasis" | "squarespace" | "system" | "seed" | "square";
                                    sqspOrderId: string | null;
                                    /** @enum {string} */
                                    status: "pending" | "done" | "denied";
