    "/api/v1/payments/invoices": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * Invoice list of a range, newest business day first
         * @description Sorted by `bizDate desc, invoiceNo desc`; keyset pagination (`nextCursor`). `filter`: all, unpaid (balance > 0), refunds (refunded or pending), adjusted, credits (credit issued or applied). `q` searches invoice id, client, vehicle and item names (case-insensitive, over the joined text like the design).
         */
        get: {
            parameters: {
                query?: {
                    cursor?: string;
                    filter?: "all" | "unpaid" | "refunds" | "adjusted" | "credits";
                    limit?: number;
                    q?: string;
                    range?: "today" | "7d" | "30d" | "mtd";
                };
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Default Response */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            items: {
                                adjusted: boolean;
                                awaiting: ("payment" | "refund") | null;
                                balanceCents: number;
                                bizDate: string;
                                /** @description The visit’s category keys (its appointment’s), in the categories’ order: the chips */
                                categories: string[];
                                /** @description The one word the visit counts under: its category ignoring add-ons, "mixed" for two or more, null for none */
                                category: string | null;
                                client: string;
                                date: string;
                                id: string;
                                invoiceNo: number;
                                items: {
                                    first: string;
                                    more: number;
                                };
                                label: string;
                                paidCents: number;
                                refundPending: boolean;
                                staff: string;
                                /** @enum {string} */
                                status: "paid" | "unpaid" | "partially_paid" | "partially_refunded" | "refunded" | "canceled" | "canceled_kept" | "canceled_refunded";
                                statusLabel: string;
                                time: string;
                                totalCents: number;
                                vehicle: string;
                            }[];
                            nextCursor: string | null;
                        };
                    };
                };
            };
        };
        put?: never;
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
