            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Default Response */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": {
                            awaitingProcessor: {
                                ageMinutes: number;
                                amountCents: number;
                                client: string;
                                eventId: string;
                                invoiceId: string;
                                label: string;
                                method: string | null;
                                occurredAt: string;
                                /** @enum {string} */
                                type: "pay" | "refund";
                            }[];
                            overpaid: {
                                bizDate: string;
                                client: string;
                                invoiceId: string;
                                label: string;
                                overpaidCents: number;
                            }[];
                            /** @description Square (ADR 0171): payments to match, card refunds Square refused (no longer counted as refunded), refund legs on their way */
                            square: {
                                failedRefunds: {
                                    amountCents: number;
                                    client: string;
                                    errors: string[];
                                    eventId: string;
                                    invoiceId: string;
                                    label: string;
                                    occurredAt: string;
                                    /** @description What Square did give back (still counted as refunded, as its own refund row) */
                                    refundedCents: number;
                                    /** @description What did not go back to the card and is not on its way: give it back another way */
                                    uncoveredCents: number;
                                }[];
                                paymentsToMatch: {
                                    ageMinutes: number;
                                    /** @description The sale, tip excluded */
                                    amountCents: number;
                                    brand: string | null;
                                    /** @description Best first (at most 5) */
                                    candidates: {
                                        /** @description The staff card entry of the same amount on that invoice: applying confirms it */
                                        awaitingEventId: string | null;
                                        balanceCents: number;
                                        client: string;
                                        invoiceId: string;
                                        invoiceNo: number;
                                        score: number;
                                        why: string[];
                                    }[];
                                    classification: string | null;
                                    createdAt: string;
                                    last4: string | null;
                                    /**
                                     * @description pending: the matcher has not decided yet (counter payments wait a little)
                                     * @enum {string}
                                     */
                                    matchState: "pending" | "unmatched";
                                    /** @description "Visa ••4242", "Cash", "Square" */
                                    method: string;
                                    note: string | null;
                                    /** @description Square payment id */
                                    paymentId: string;
                                    /** @description SQUARE_POS, ECOMMERCE_API, ... */
                                    product: string | null;
                                    receiptNumber: string | null;
                                    refundedCents: number;
                                    sourceType: string | null;
                                    tipCents: number;
                                    totalCents: number;
                                }[];
                                refundsInFlight: number;
                            };
                            thresholdMinutes: number;
                            unmatchedOrders: {
                                createdAt: string;
                                customerEmail: string | null;
                                orderNumber: string | null;
                                sqspOrderId: string;
                                totalCents: number;
                            }[];
                            unmatchedTransactions: {
                                amountCents: number;
                                createdAt: string;
                                /** @enum {string} */
                                kind: "payment" | "refund";
                                sqspOrderId: string | null;
                                sqspTransactionId: string;
                            }[];
                        };
                    };
                };
            };
