                        public: boolean;
                        /** @description Memberships, links or checkouts name it: it can be turned off, never deleted */
                        sold: boolean;
                        sort: number;
                        /** @description Staff with set.services only */
                        squarePlanId?: string | null;
                        /** @description The token PUT /catalog/tiers/{key} takes */
                        version: number;
                        /** @description Members get the VIP slot rules */
                        vipBooking: boolean;
