    getSquareItems: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Default Response */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        counts: {
                            archived: number;
                            failed: number;
                            notSold: number;
                            onSquare: number;
                            waiting: number;
                        };
                        /** @enum {string} */
                        environment: "sim" | "sandbox" | "production";
                        failures: {
                            error: string | null;
                            service: string;
                            serviceId: string;
                        }[];
                        itemsSyncEnabled: boolean;
                        lastDriftAt: string | null;
                        lastError: string | null;
                        lastErrorAt: string | null;
                        lastSync: {
                            [key: string]: unknown;
                        } | null;
                        lastSyncAt: string | null;
                        lastWriteAt: string | null;
                        /**
                         * @description on: the sync writes; preview: watch-only (SQUARE_WRITES_ENABLED=false); off: SQUARE_ITEMS_SYNC_ENABLED=false
                         * @enum {string}
                         */
                        mode: "on" | "preview" | "off";
                        /** @description The last read-only preview (POST …/items/sync while the sync is not on) */
                        preview: {
                            archive: number;
                            /** Format: date-time */
                            at: string;
                            /** @description Categories the sync would make (or adopt by name) */
                            categories: number;
                            /** @description Items the sync would make */
                            create: number;
                            /** @description Prices (variations) on them */
                            createPrices: number;
                            /** @description Services not sold (off, quote-only, no price) and never made */
                            skipped: number;
                            /** @enum {string} */
                            tax: "create" | "update" | "adopt" | "none" | "blocked";
                            unchanged: number;
                            update: number;
                        } | null;
                        taxCheck: {
                            /** @description The enabled Square taxes at the shop (Oasis’s own excluded): what PUT …/items/tax can adopt */
                            candidates: {
                                id: string;
                                matches: boolean;
                                name: string;
                                percentage: string | null;
                                problem: string | null;
                            }[];
                            /** @description In plain words */
                            detail: string;
                            /** @enum {string} */
                            mode: "auto" | "adopt" | "create";
                            /** @description Oasis made this tax: the sync keeps it at Oasis’s rate */
                            own: boolean;
                            /** @description Oasis’s own tax only: what was changed in Square besides its percentage ("turned off", "included in the price, not added to it", …); the next sync puts it back */
                            ownChanged: string[];
                            /** @description Square’s percentage of that tax, as Square writes it ("6.625") */
                            percentage: string | null;
                            rounding?: {
                                checked: number;
                                detail: string;
                                differ: number;
                            };
                            /**
                             * @description ok: Oasis items use taxId; create: the sync will add Oasis’s own; blocked or error: the sync is paused
                             * @enum {string}
                             */
                            status: "ok" | "create" | "blocked" | "error";
                            taxId: string | null;
                            taxName: string | null;
                            /** @description Oasis’s rate (tax.rate_dbp) as a Square percentage */
                            wantPercentage: string;
                            warnings: string[];
                        } | null;
                        taxCheckedAt: string | null;
                        /** @enum {string} */
                        taxMode: "auto" | "adopt" | "create";
                        /** @description mode adopt: the Square tax picked */
                        taxObjectId: string | null;
                        /** @description The token PUT /integrations/square/items/tax takes */
                        version: number;
                        writesEnabled: boolean;
                    };
                };
            };
        };
    };
