    getSettingsAssistant: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Default Response */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description The assistant may book, reschedule and cancel in the chat, each confirmed by a reply number (with AI_ACTIONS_ENABLED on the server) */
                        actionsEnabled: boolean;
                        /** @description Read-only: the assistant answers texts now (AI_ENABLED and enabled) */
                        active: boolean;
                        /** @description The numbers of the first stage (the owner and staff), E.164 (+12015550142; "(201) 555-0142" is read too), textable US/Canadian numbers, at most 50, each once. GET shows them masked to the last four digits ("+1******0142") to a reader without set.assistant */
                        allowlist: string[];
                        /** @description ADR 0174 tone: how the assistant writes (defaults = today): the owner block after the rules, words to avoid (guard), topics handed to the team (server backstop), the Spanish mode and the server's sign-off */
                        behavior: {
                            /** @description Topics it does not discuss: 3 to 80 characters each, at most 15, each once */
                            avoidTopics: string[];
                            /** @description Words and phrases it never uses: 2 to 40 characters each, at most 30, each once */
                            avoidWords: string[];
                            /** @description Topics it always hands to the team: 3 to 80 characters each, at most 15, each once, none also in avoidTopics */
                            handoffTopics: string[];
                            /**
                             * @description The reply length it aims for (320 characters stays the hard cap)
                             * @enum {string}
                             */
                            length: "short" | "standard";
                            /** @description An optional sign-off the server adds, at most 24 characters, no amount, number, link or promise ("" = none) */
                            signOff: string;
                            /**
                             * @description Spanish texts: answer in Spanish, answer in English, or hand them to the team
                             * @enum {string}
                             */
                            spanish: "on" | "english" | "handoff";
                            /** @description The owner’s style preferences, plain text, at most 400 characters (quoted to the model as data) */
                            styleNotes: string;
                            /**
                             * @description A fixed, vetted tone sentence
                             * @enum {string}
                             */
                            tone: "friendly" | "professional" | "warm" | "concise";
                        };
                        /** @description ADR 0174 limits: what the assistant may do (all on by default = today). Settings only take abilities away; booking, moving and cancelling by text stays `actionsEnabled`. "Answer questions only" is all five off (with actionsEnabled off). A switched-off ability is left out of the model’s tools and refused if called */
                        capabilities: {
                            /** @description It may tell a client their balance, visits and membership */
                            accountInfo: boolean;
                            /** @description It may look up open times (check_availability) */
                            availability: boolean;
                            /** @description It may text booking and verify links */
                            bookingLinks: boolean;
                            /** @description It may text a link to join a membership */
                            membershipLinks: boolean;
                            /** @description It may text a link to pay an open invoice */
                            paymentLinks: boolean;
                        };
                        /** @description The assistant answers texts (with AI_ENABLED on the server); off: texts reach staff as today */
                        enabled: boolean;
                        /** @description Questions and answers the assistant answers from, at most 40 pairs, plain text, each question once */
                        faq: {
                            /** @description The answer the assistant gives, plain text, 500 characters at most */
                            a: string;
                            /** @description The question as a client would ask it, plain text, 500 characters at most */
                            q: string;
                        }[];
                        /** @description Read-only: the server switches (environment), which this section cannot change */
                        server: {
                            /** @description AI_ACTIONS_ENABLED: off, no in-chat booking, rescheduling or cancelling */
                            actionsEnabled: boolean;
                            /** @description AI_ENABLED: off, the assistant answers nobody whatever this section says */
                            aiEnabled: boolean;
                        };
                        /** @description A staff reply pauses the assistant on that thread this many hours, 1 to 72 */
                        staffPauseHours: number;
                        /**
                         * @description Who it answers: only the allowlisted numbers, then also known clients, then everyone
                         * @enum {string}
                         */
                        stage: "allowlist" | "customers" | "everyone";
                        /** @description The section’s version (ETag): send it back with PUT */
                        version: number;
                    };
                };
            };
        };
    };
